import java.util.*;
import java.io.*;

public class Main {
    static final FastReader sc = new FastReader();

    public static void main(String[] args) {
        char[] a = sc.next().toCharArray();
        if (a.length == 1 && a[0] == '0') {
            System.out.println(1);
            return;
        }
        if (a[0] == '0') {
            System.out.println(0);
            return;
        }
        if (a.length == 1 && (a[0] == 'X' || a[0] == '_')) {
            System.out.println(1);
            return;
        }

        Map<Long, Long> memo = new HashMap<>();
        System.out.println(dfs(a, 0, 0, 10, memo));
    }

    static long dfs(char[] a, int i, int rem, int x, Map<Long, Long> memo) {
        if (i == a.length) {
            return rem == 0 ? 1 : 0;
        }
        long key = ((long) i * 275) + rem * 11 + x;
        Long cached = memo.get(key);
        if (cached != null) {
            return cached;
        }

        long ans = 0;
        if (a[i] == '_') {
            for (int d = 0; d < 10; d++) {
                if (i == 0 && d == 0) continue;
                ans += dfs(a, i + 1, (rem * 10 + d) % 25, x, memo);
            }
        } else if (a[i] == 'X') {
            if (x != 10) {
                ans += dfs(a, i + 1, (rem * 10 + x) % 25, x, memo);
            } else {
                for (int d = 0; d < 10; d++) {
                    if (i == 0 && d == 0) continue;
                    ans += dfs(a, i + 1, (rem * 10 + d) % 25, d, memo);
                }
            }
        } else {
            ans += dfs(a, i + 1, (rem * 10 + a[i] - '0') % 25, x, memo);
        }

        memo.put(key, ans);
        return ans;
    }

    static class FastReader {
        BufferedReader br;
        StringTokenizer st;

        FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }
    }
}
